        // Case 2: non-empty vector
        // We scan with two indices: `min_idx` points to the current minimum,
        // `idx` scans from 1 up to s.len().
        let mut min_idx: usize = 0;
        let mut idx: usize = 1;

        // Establish the loop invariant at the start:
